const server=http.createServer(async(req,res)=>{
  try{const url=new URL(req.url,'http://localhost');if(url.pathname.startsWith('/api/'))return await api(req,res,url);if(req.method!=='GET'&&req.method!=='HEAD')return send(res,405,{error:'Método não permitido.'});if((url.pathname==='/'||url.pathname==='/index.html')&&!sessionFrom(req)){res.writeHead(302,{location:'/login.html?next=%2F','cache-control':'no-store'});return res.end();}const requested=decodeURIComponent(url.pathname==='/'?'index.html':url.pathname.slice(1));const target=path.resolve(root,requested);if(!target.startsWith(root+path.sep)&&target!==root)return send(res,403,{error:'Acesso negado.'});if(target===dataDir||target.startsWith(dataDir+path.sep))return send(res,403,{error:'Acesso negado.'});const file=await fs.readFile(target);res.writeHead(200,{'content-type':mime[path.extname(target)]||'application/octet-stream','cache-control':'no-store','x-content-type-options':'nosniff','referrer-policy':'strict-origin-when-cross-origin','x-frame-options':'DENY'});res.end(req.method==='HEAD'?undefined:file);}catch(error){if(error.code==='ENOENT')return send(res,404,{error:'Página não encontrada.'});send(res,error.status||500,{error:error.status?error.message:'Erro interno do servidor.'});if(!error.status)console.error(error);}
});
initialize().then(()=>server.listen(port,()=>console.log(`RS TECH disponível em http://localhost:${port}`))).catch(error=>{console.error(error.message);process.exitCode=1;});
